"""gpujob_core: the parts of gpujob that every machine runs: file helpers, the job model, the on-disk state and the
per-GPU worker. Imported by gpujob.py (the command line); see its docstring. Standard library only.
"""
from __future__ import annotations

import ctypes, fcntl, glob as globmod, hashlib, json, os, re, shutil, signal, socket, statistics
import subprocess, sys, threading, time, uuid

POLL = float(os.environ.get("GPUJOB_POLL", "1"))  # worker/supervisor tick; tests lower it
LEASES = ("lease", "spec", "commit")  # claim, speculative claim, commit-in-progress marker


# ---------------------------------------------------------------------------------------------- helpers
def now():
    return time.time()


def quiet(fn, *a, **kw):
    """fn(*a, **kw), or None if it raises (best-effort cleanup and probes)."""
    try:
        return fn(*a, **kw)
    except Exception:
        return None


def host_id():
    """This machine: hostname + kernel boot id (sandboxes often share one hostname), else a random id inherited by the
    runner's workers through GPUJOB_HOSTID."""
    boot = quiet(lambda: open("/proc/sys/kernel/random/boot_id").read().strip()[:8]) or uuid.uuid4().hex[:8]
    return os.environ.get("GPUJOB_HOSTID") or f"{socket.gethostname()}:{boot}"


HOST = host_id()


def try_lock(f):
    try:
        fcntl.flock(f, fcntl.LOCK_EX | fcntl.LOCK_NB)
        return True
    except OSError:
        return False


def fsync_dir(path):
    fd = quiet(os.open, path, os.O_RDONLY)
    if fd is not None:
        quiet(os.fsync, fd)
        os.close(fd)


def write_atomic(path, data):
    """Readers see the old file or the whole new one, never a partial write."""
    d = os.path.dirname(path) or "."
    os.makedirs(d, exist_ok=True)
    tmp = os.path.join(d, f".{os.path.basename(path)}.{os.getpid()}.{threading.get_ident()}.tmp")
    with open(tmp, "wb") as f:
        f.write(data.encode() if isinstance(data, str) else data)
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, path)
    fsync_dir(d)


def write_json(path, obj):
    write_atomic(path, json.dumps(obj, indent=1, sort_keys=True))


def read_json(path, default=None):
    try:
        with open(path) as f:
            return json.load(f)
    except (OSError, ValueError):
        return default


def read_jsonl(path):
    """Records of a JSON-lines file; a line cut by a crash is skipped."""
    try:
        with open(path) as f:
            return [r for r in (quiet(json.loads, line) for line in f) if r is not None]
    except OSError:
        return []


def append_jsonl(path, obj):
    fd = os.open(path, os.O_WRONLY | os.O_APPEND | os.O_CREAT, 0o644)
    try:
        os.write(fd, (json.dumps(obj, sort_keys=True) + "\n").encode())  # one O_APPEND write per record
    finally:
        os.close(fd)


def tail(path, n):
    try:
        with open(path, "rb") as f:
            f.seek(max(0, os.path.getsize(path) - n))
            return f.read().decode(errors="replace")
    except OSError:
        return ""


def rm(path):
    if os.path.isdir(path) and not os.path.islink(path):
        shutil.rmtree(path, ignore_errors=True)
    else:
        quiet(os.unlink, path)


def sha256_file(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for b in iter(lambda: f.read(1 << 20), b""):
            h.update(b)
    return h.hexdigest()


def fmt_s(s):
    if s is None:
        return "?"
    s = int(round(s))
    return f"{s}s" if s < 120 else f"{s // 60}m{s % 60:02d}s" if s < 7200 else f"{s // 3600}h{(s % 3600) // 60:02d}m"


def out(line):
    """Runner stdout carries GPUJOB lines only (a progress tray reads the last 4 KiB of the log)."""
    sys.stdout.write(line.rstrip("\n") + "\n")
    sys.stdout.flush()


def pid_alive(pid):
    try:
        os.kill(pid, 0)
    except ProcessLookupError:
        return False
    except PermissionError:
        pass
    return True


def kill_env(key, value, sig=signal.SIGKILL):
    """Signal every process whose environment has key=value: a command's whole tree, grandchildren included."""
    needle, pids = f"{key}={value}".encode(), []
    for p in os.listdir("/proc") if os.path.isdir("/proc") else []:
        if p.isdigit() and int(p) != os.getpid():
            try:
                with open(f"/proc/{p}/environ", "rb") as f:
                    if needle in f.read().split(b"\0"):
                        pids.append(int(p))
                        os.kill(int(p), sig)
            except OSError:
                pass
    return pids


def die_with_parent():
    """preexec_fn: SIGKILL the child when its parent dies (Linux), so a killed worker never leaves a GPU busy."""
    quiet(lambda: ctypes.CDLL(None).prctl(1, signal.SIGKILL))  # PR_SET_PDEATHSIG


def subst(arg, vals):
    return re.sub(r"\{(start|end|chunk|tmp|out|gpu|attempt)\}", lambda m: str(vals[m.group(1)]), arg)


def unit_number(name):
    nums = re.findall(r"\d+", os.path.basename(name))
    return int(nums[-1]) if nums else None


def unit_files(base, pattern):
    """Committed files matching pattern under base: whole, non-empty, not hidden, not .tmp/.partial."""
    return [f for f in globmod.glob(os.path.join(base, pattern)) if not os.path.basename(f).startswith(".")
            and not f.endswith((".tmp", ".partial")) and (quiet(os.path.getsize, f) or 0) > 0]


# ---------------------------------------------------------------------------------------------- job and state
class Stage:
    def __init__(self, d, workdir, retries):
        self.d, self.name, self.kind, self.cmd = d, d["name"], d.get("kind", "chunks"), d["cmd"]
        if self.kind not in ("chunks", "sequential"):
            raise SystemExit(f"gpujob: stage {self.name}: kind must be chunks or sequential")
        self.out_rel = d.get("out", f"out/{self.name}")
        self.out = os.path.join(workdir, self.out_rel)
        self.after, self.timeout = d.get("after"), d.get("timeout")
        self.harvest = d.get("harvest", self.kind == "chunks")
        self.retries = d.get("retries", retries)
        self.unit_label = d.get("unit_label", "frames" if self.kind == "chunks" else "units")
        self.outputs = self.unit_glob = self.checkpoint = None
        if self.kind == "chunks":
            a, b = d["range"]
            n, w = int(d.get("chunk", 1)), max(4, len(str(b)))
            self.chunks = {f"{s:0{w}d}-{min(s + n - 1, b):0{w}d}": (s, min(s + n - 1, b)) for s in range(a, b + 1, n)}
            self.total_units = b - a + 1
            self.outputs = [d["outputs"]] if isinstance(d.get("outputs"), str) else d.get("outputs")
        else:
            self.chunks, self.total_units = {"all": (None, None)}, int(d["units"])
            self.unit_glob = d.get("unit_glob", "*")
            self.checkpoint = d.get("checkpoint")  # glob under workdir, written tmp-then-rename after its unit

    def expected(self, cid):
        s, e = self.chunks[cid]
        return [p.format(frame=f, chunk=cid, start=s, end=e) for f in range(s, e + 1) for p in self.outputs or []]

    def layout(self):
        return {"kind": self.kind, "chunks": sorted(self.chunks), "out": self.out_rel}


class Job:
    def __init__(self, spec, path=None):
        self.spec, self.name = spec, spec["name"]
        base = os.path.dirname(os.path.abspath(path)) if path else os.getcwd()
        self.workdir = os.path.abspath(os.path.join(base, spec.get("workdir", ".")))
        self.rate = float(spec.get("credits_per_gpu_minute", 0)) / 60  # credits per GPU-second (offers, gpus 1)
        self.retries, self.lease_seconds = int(spec.get("retries", 3)), float(spec.get("lease_seconds", 120))
        self.stages = [Stage(d, self.workdir, self.retries) for d in spec["stages"]]
        self.by = {s.name: s for s in self.stages}
        for s in self.stages:
            if s.after and s.after.get("stage") not in self.by:
                raise SystemExit(f"gpujob: stage {s.name}: after.stage {s.after.get('stage')!r} not found")

    @classmethod
    def load(cls, path):
        with open(path) as f:
            return cls(json.load(f), path)

    def dependents(self, names):
        """names plus every stage that (transitively) depends on them."""
        got = set(names)
        while True:
            more = {s.name for s in self.stages if s.after and s.after["stage"] in got} - got
            if not more:
                return got
            got |= more


class State:
    """<state>/job.json run.json run.lock progress.json events.jsonl chunks/<stage>/<id>.lease|.spec|.commit|.done|.fail
    logs/<stage>/<id>.<attempt>.log gpus/<gpu>.quarantined. One state dir belongs to one machine."""

    def __init__(self, root, job=None):
        self.root = os.path.abspath(root)
        if job is None and not os.path.exists(self.p("job.json")):
            raise SystemExit(f"gpujob: no job.json in state dir {self.root} (has `run` been started there?)")
        self.job = job or Job(read_json(self.p("job.json")), self.p("job.json"))
        self.run, self._done = read_json(self.p("run.json"), {}), {}  # .done records never change once written

    def p(self, *a):
        return os.path.join(self.root, *a)

    def cpath(self, stage, cid, ext):
        return self.p("chunks", stage, f"{cid}.{ext}")

    def event(self, kind, **kw):
        append_jsonl(self.p("events.jsonl"), dict(kw, ev=kind, t=round(now(), 3), host=HOST))

    def done(self, stage, cid):
        if (stage, cid) not in self._done:
            d = read_json(self.cpath(stage, cid, "done"))
            if d is None:
                return None
            self._done[(stage, cid)] = d
        return self._done[(stage, cid)]

    def index(self, stage):
        """One listdir: sets of chunk ids per file kind (cheap at 20,000 chunks)."""
        idx = {"done": set(), "lease": set(), "spec": set(), "fail": set()}
        for f in quiet(os.listdir, self.p("chunks", stage)) or []:
            cid, _, ext = f.rpartition(".")
            if ext in idx:
                idx[ext].add(cid)
        return idx

    def done_ids(self, stage):
        return self.index(stage)["done"]

    def fails(self, stage, cid):
        return read_jsonl(self.cpath(stage, cid, "fail"))

    def lease(self, stage, cid, ext="lease"):
        path = self.cpath(stage, cid, ext)
        mtime = quiet(os.path.getmtime, path)
        return None if mtime is None else dict(read_json(path) or {}, _age=now() - mtime)

    def lease_live(self, info):
        """Live while its heartbeat is fresh and (on this host) its worker process exists."""
        if info is None or (info.get("host") == HOST and info.get("pid") and not pid_alive(info["pid"])):
            return False
        return info["_age"] < self.job.lease_seconds

    def quarantined(self):
        return {f.split(".")[0] for f in quiet(os.listdir, self.p("gpus")) or [] if f.endswith(".quarantined")}

    def units(self, st):
        """Committed unit numbers: frames of .done chunks, or a sequential stage's final unit files."""
        if st.kind == "chunks":
            return {f for c in self.done_ids(st.name) if c in st.chunks for f in range(st.chunks[c][0], st.chunks[c][1] + 1)}
        return {n for n in map(unit_number, unit_files(st.out, st.unit_glob)) if n is not None}

    def selected(self, st):
        """This run's chunks of a stage (--stages, --only, --partition)."""
        if self.run.get("stages") and st.name not in self.run["stages"]:
            return []
        ids, only, part = list(st.chunks), self.run.get("only"), self.run.get("partition")
        if only:
            ids = [c for c in ids if f"{st.name}:{c}" in only or c in only]
        return [c for k, c in enumerate(ids) if k * part[1] // len(ids) == part[0]] if part else ids

    def deps_met(self, st, cid, cache):
        a = st.after
        if not a:
            return True
        up = self.job.by[a["stage"]]
        if a.get("map", "all") == "all" or st.kind == "sequential":
            return set(up.chunks) <= self.done_ids(up.name)
        if up.name not in cache:
            cache[up.name] = self.units(up)
        sc, off = float(a.get("scale", 1)), float(a.get("offset", 0))
        return all(int(round(f * sc + off)) in cache[up.name] for f in range(st.chunks[cid][0], st.chunks[cid][1] + 1))

    def scan(self):
        """{stage: {done, leased, failed, ready, waiting: [ids], fail_ids: set}} for this run's chunks."""
        res, cache, rid = {}, {}, self.run.get("run_id")
        for st in self.job.stages:
            idx = self.index(st.name)
            r = res[st.name] = {"done": [], "leased": [], "failed": [], "ready": [], "waiting": [], "fail_ids": idx["fail"]}
            for cid in self.selected(st):
                if cid in idx["done"]:
                    r["done"].append(cid)
                elif any(cid in idx[x] and self.lease_live(self.lease(st.name, cid, x)) for x in ("lease", "spec")):
                    r["leased"].append(cid)
                elif cid in idx["fail"] and sum(1 for f in self.fails(st.name, cid) if f.get("run_id") == rid
                                                and not f.get("progress")) > st.retries:
                    r["failed"].append(cid)  # a sequential crash that made progress doesn't use up a retry
                elif self.deps_met(st, cid, cache):
                    r["ready"].append(cid)
                else:
                    r["waiting"].append(cid)
        return res


# ---------------------------------------------------------------------------------------------- worker
class Worker:
    """One per GPU: claim a chunk (O_EXCL lease + heartbeat), run it into a private tmp dir, then commit: one copy
    takes the .commit marker, moves verified outputs into place with os.replace and links <id>.done."""

    def __init__(self, S, gpu):
        self.S, self.gpu, self.wid = S, gpu, f"{HOST}:{os.getpid()}:g{gpu}"
        self.stop, self.token, self.ext, self.consec = False, None, "lease", []  # consec: failures in a row here
        for sig in (signal.SIGTERM, signal.SIGINT):
            signal.signal(sig, self._term)

    def _term(self, *_):
        self.stop = True
        if self.token:
            kill_env("GPUJOB_TOKEN", self.token, signal.SIGTERM)

    def others(self):
        q = self.S.quarantined()
        return [g for g in self.S.run.get("gpus", []) if g != self.gpu and g not in q]

    def pick(self):
        sc, cands = self.S.scan(), []
        for k, st in enumerate(self.S.job.stages):
            for cid in sc[st.name]["ready"]:
                f = self.S.fails(st.name, cid) if cid in sc[st.name]["fail_ids"] else []
                mine = bool(f) and str(f[-1].get("gpu")) == self.gpu
                if mine and self.others() and now() - f[-1].get("t", 0) < 5 * POLL + 5:
                    continue  # give another GPU the first go at a chunk that just failed here
                # most downstream ready stage first: final frames appear early, total work is the same
                cands.append((st.kind != "sequential", mine, -k, st.name, cid, len(f) + 1))
        if not cands:
            return self.speculate(sc)
        _, _, _, sname, cid, attempt = min(cands)
        return self.S.job.by[sname], cid, attempt, "lease"

    def speculate(self, sc):
        """Nothing left to claim: duplicate the oldest in-flight chunk running > 1.5x its stage's median time."""
        S, best = self.S, None
        for st in S.job.stages if os.environ.get("GPUJOB_SPECULATE") != "0" else []:  # off for estimate --pilot
            secs = [d.get("seconds", 0) for d in (S.done(st.name, c) for c in sc[st.name]["done"]) if d]
            if st.kind != "chunks" or not secs:
                continue
            med, spec = statistics.median(secs), S.index(st.name)["spec"]
            for cid in sc[st.name]["leased"]:
                l = S.lease(st.name, cid)
                if l and l.get("t") and str(l.get("gpu")) != self.gpu and cid not in spec:
                    age = now() - l["t"]
                    if age > 1.5 * med + POLL and (best is None or age > best[0]):
                        best = (age, st, cid, l.get("attempt", 1))
        return (best[1], best[2], best[3], "spec") if best else None

    def claim(self, st, cid, attempt, ext):
        path = self.S.cpath(st.name, cid, ext)
        os.makedirs(os.path.dirname(path), exist_ok=True)
        info = self.S.lease(st.name, cid, ext)
        if info is not None:
            if self.S.lease_live(info):
                return False
            try:  # steal a stale lease: only one stealer wins the rename
                os.rename(path, f"{path}.stale.{uuid.uuid4().hex[:8]}")
            except OSError:
                return False
            kill_env("GPUJOB_TOKEN", info.get("token"))
            [rm(f) for f in globmod.glob(path + ".stale.*")]
            self.S.event("lease_stolen", stage=st.name, chunk=cid, worker=self.wid, prev=info.get("worker"))
        if self.S.done(st.name, cid):
            return False
        try:
            fd = os.open(path, os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o644)
        except FileExistsError:
            return False
        self.token, self.ext = uuid.uuid4().hex, ext
        with os.fdopen(fd, "w") as f:
            json.dump(dict(worker=self.wid, host=HOST, pid=os.getpid(), gpu=self.gpu, token=self.token,
                           run_id=self.S.run.get("run_id"), attempt=attempt, t=now()), f)
        if self.S.done(st.name, cid):  # committed between our check and our lease
            self.release(st, cid)
            return False
        return True

    def release(self, st, cid):
        rm(self.S.cpath(st.name, cid, self.ext))
        self.token = None

    def heartbeat(self, path, stop):
        while not stop.wait(min(10.0, self.S.job.lease_seconds / 4)):
            quiet(os.utime, path)

    def execute(self, st, cid, attempt):
        """Run one claimed chunk. True committed, False failed, None abandoned (SIGTERM, or the other copy won)."""
        S, spec = self.S, self.ext == "spec"
        lease, done_p, mark = (S.cpath(st.name, cid, x) for x in (self.ext, "done", "commit"))
        tmp = os.path.join(st.out, ".tmp", f"{cid}.{attempt}{'s' if spec else ''}.{os.getpid()}")
        rm(tmp)
        os.makedirs(tmp if st.kind == "chunks" else st.out, exist_ok=True)
        carried = self.carry(st, cid, tmp)
        if carried:
            S.event("chunk_carried", stage=st.name, chunk=cid, gpu=self.gpu, outputs=carried)
        s, e = st.chunks[cid]
        vals = dict(start=s, end=e, chunk=cid, tmp=tmp, out=st.out, gpu=self.gpu, attempt=attempt)
        cmd = [subst(a, vals) for a in st.cmd] if isinstance(st.cmd, list) else ["sh", "-c", subst(st.cmd, vals)]
        logp = S.p("logs", st.name, f"{cid}.{attempt}{'s' if spec else ''}.log")
        os.makedirs(os.path.dirname(logp), exist_ok=True)
        env = dict(os.environ, CUDA_VISIBLE_DEVICES=self.gpu, GPUJOB_GPU=self.gpu, GPUJOB_STATE=S.root, GPUJOB_CHUNK=cid,
                   GPUJOB_WORKER=self.wid, GPUJOB_TOKEN=self.token, GPUJOB_ATTEMPT=str(attempt), GPUJOB_STAGE=st.name)
        units0 = len(S.units(st)) if st.kind == "sequential" else 0
        S.event("chunk_start", stage=st.name, chunk=cid, gpu=self.gpu, attempt=attempt, worker=self.wid, spec=spec)
        hb = threading.Event()
        threading.Thread(target=self.heartbeat, args=(lease, hb), daemon=True).start()
        t0, rc, why = now(), None, ""
        try:
            with open(logp, "ab") as logf:
                logf.write(f"$ {' '.join(cmd)}\n".encode())
                logf.flush()
                child = subprocess.Popen(cmd, cwd=S.job.workdir, env=env, stdout=logf, stderr=subprocess.STDOUT,
                                         stdin=subprocess.DEVNULL, preexec_fn=die_with_parent)
                while rc is None:
                    rc = quiet(child.wait, timeout=POLL)
                    if rc is None and os.path.exists(done_p):
                        why = "superseded"  # the other copy (speculative or original) committed first
                    elif rc is None and st.timeout and now() - t0 > st.timeout:
                        why = f"timeout after {st.timeout}s"
                    if rc is None and why:
                        kill_env("GPUJOB_TOKEN", self.token)
                        rc = child.wait()
        except OSError as ex:
            rc, why = 127, f"could not start: {ex}"
        finally:
            hb.set()
            kill_env("GPUJOB_TOKEN", self.token)  # nothing of this attempt may outlive it
        secs = round(now() - t0, 3)
        if rc == 0 and not why and not self.stop:  # exactly one copy may move outputs into place
            try:
                fd = os.open(mark, os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o644)
                os.write(fd, json.dumps({"worker": self.wid, "run_id": S.run.get("run_id")}).encode())
                os.close(fd)
                if S.done(st.name, cid):
                    rm(mark)
                    why = "superseded"
            except FileExistsError:
                why = "superseded"
        if (self.stop or rc == -signal.SIGTERM) and os.path.exists(done_p):
            why = "superseded"
        if self.stop or rc == -signal.SIGTERM or why == "superseded":  # abandon cleanly: the chunk is just un-leased
            self.release(st, cid)
            S.event("chunk_superseded" if why else "chunk_abandoned", stage=st.name, chunk=cid, gpu=self.gpu,
                    spec=spec, seconds=secs)
            if why:  # stopped (SIGTERM): finished outputs stay in tmp for the next attempt to carry over
                [rm(f) for f in [tmp] + globmod.glob(tmp + "-*")]
            return None
        if rc == 0 and not why:
            try:
                rec = self.commit(st, cid, tmp) if st.kind == "chunks" else self.commit_seq(st)
                rec.update(seconds=secs, gpu=self.gpu, attempt=attempt, worker=self.wid, speculative=spec,
                           run_id=S.run.get("run_id"), t=now())
                dt = S.cpath(st.name, cid, "done.tmp." + self.token)
                try:
                    write_atomic(dt, json.dumps(rec))
                    os.link(dt, done_p)
                    fsync_dir(os.path.dirname(done_p))
                    S.event("chunk_done", stage=st.name, chunk=cid, gpu=self.gpu, seconds=secs, spec=spec)
                except FileExistsError:
                    S.event("chunk_duplicate", stage=st.name, chunk=cid, gpu=self.gpu)
                finally:
                    rm(dt)
                    rm(mark)
                [rm(f) for f in [tmp] + globmod.glob(tmp + "-*")]
                self.release(st, cid)
                return True
            except CommitError as ex:
                why = str(ex)
                rm(mark)
        progress = len(S.units(st)) - units0 if st.kind == "sequential" else 0
        append_jsonl(S.cpath(st.name, cid, "fail"), dict(rc=rc, why=why, gpu=self.gpu, attempt=attempt, seconds=secs,
                     run_id=S.run.get("run_id"), t=now(), progress=progress, worker=self.wid,
                     log=os.path.relpath(logp, S.root), tail=tail(logp, 2000)))
        S.event("chunk_fail", stage=st.name, chunk=cid, gpu=self.gpu, rc=rc, why=why, attempt=attempt)
        self.release(st, cid)  # tmp stays: the retry carries its finished outputs over
        return False

    def carry(self, st, cid, tmp):
        """Move whole outputs (the stage's `outputs` names; hidden partials are dropped) that dead attempts of this
        chunk left in .tmp/ into the new attempt's folder, so a command run with --resume redoes only what's missing.
        A live copy's folder (the speculative twin or the original) is never touched."""
        if st.kind != "chunks" or not st.outputs:
            return 0
        other = "spec" if self.ext == "lease" else "lease"
        info = self.S.lease(st.name, cid, other)
        live = str(info.get("pid")) if self.S.lease_live(info) else None
        n = 0
        for d in globmod.glob(os.path.join(st.out, ".tmp", f"{cid}.*")):
            if d == tmp or not os.path.isdir(d) or d.rsplit(".", 1)[-1] == live:
                continue
            for rel in st.expected(cid):
                src, dst = os.path.join(d, rel), os.path.join(tmp, rel)
                if (quiet(os.path.getsize, src) or 0) > 0 and not os.path.exists(dst):
                    os.makedirs(os.path.dirname(dst), exist_ok=True)
                    os.replace(src, dst)
                    n += 1
            [rm(f) for f in [d] + globmod.glob(d + "-*")]
        return n

    def commit(self, st, cid, tmp):
        exp = st.expected(cid) or sorted(os.path.relpath(os.path.join(dp, f), tmp) for dp, _, fs in os.walk(tmp)
                                         for f in fs if not f.startswith("."))
        if not exp:
            raise CommitError(f"command exited 0 but wrote no files into {tmp}")
        for rel in exp:
            if (quiet(os.path.getsize, os.path.join(tmp, rel)) or 0) == 0:
                raise CommitError(f"missing or empty output {rel}")
        files = []
        for rel in exp:
            src, dst = os.path.join(tmp, rel), os.path.join(st.out, rel)
            with open(src, "rb") as f:
                os.fsync(f.fileno())
            files.append({"path": rel, "bytes": os.path.getsize(src), "sha256": sha256_file(src)})
            os.makedirs(os.path.dirname(dst), exist_ok=True)
            os.replace(src, dst)
            fsync_dir(os.path.dirname(dst))
        return {"outputs": files, "bytes": sum(f["bytes"] for f in files)}

    def commit_seq(self, st):
        n = len(self.S.units(st))
        if n < st.total_units:
            raise CommitError(f"exited 0 with {n}/{st.total_units} units committed")
        return {"units": n}

    def judge(self):
        """After 2+ failures in a row here: 'gpu' once all of those chunks succeeded on other GPUs while other GPUs
        finish fresh chunks first time; 'job' if another GPU failed meanwhile (flaky chunks); None: undecided."""
        S, t0, fresh_ok = self.S, self.consec[0][2], False
        for st in S.job.stages:
            idx = S.index(st.name)
            for cid in idx["fail"]:
                if any(str(f.get("gpu")) != self.gpu and f.get("t", 0) >= t0 for f in S.fails(st.name, cid)):
                    return "job"
            for cid in idx["done"] - idx["fail"]:
                d = S.done(st.name, cid) or {}
                fresh_ok = fresh_ok or (str(d.get("gpu")) != self.gpu and d.get("t", 0) >= t0)
        moved = all(str((S.done(sn, cid) or {}).get("gpu", self.gpu)) != self.gpu for sn, cid, _ in self.consec)
        return "gpu" if moved and fresh_ok else None

    def main(self):
        S = self.S
        S.event("worker_start", gpu=self.gpu, worker=self.wid)
        while not self.stop and self.gpu not in S.quarantined():
            if len(self.consec) >= 2:
                v = self.judge() if self.others() else "job"
                if v == "gpu":
                    write_json(S.p("gpus", f"{self.gpu}.quarantined"), dict(t=now(), chunks=self.consec, worker=self.wid))
                    S.event("gpu_quarantined", gpu=self.gpu, chunks=[f"{a}:{b}" for a, b, _ in self.consec])
                    return 0
                if v is None:
                    time.sleep(POLL)
                    continue
                self.consec = []
            got = self.pick()
            if not got:
                time.sleep(POLL)
                continue
            if not self.claim(*got):
                continue
            ok = self.execute(*got[:3])
            if ok is True:
                self.consec = []
            elif ok is False:
                self.consec.append((got[0].name, got[1], now()))
        return 0


class CommitError(Exception):
    pass

#!/usr/bin/env python3
"""gpujob_fanout: run one gpujob job over several GPU machines from your computer.

  gpujob_fanout.py fanout job.json --machines M --gpus-per-machine G [--transport voyager|<plug-in>] \
      [--to DIR] [--push PATHS] [--poll 30] [--place-timeout 600] [--cpu N] [--ram-gib N] [--idle-s 900]

Run it as a tracked job so it outlives the turn and wakes the conversation when it ends:
  voyager jobs run --title "Render hero" -- python3 gpujob_fanout.py fanout render/job.json --machines 2 ...

Each machine runs `gpujob.py run --only <its chunks>`; every poll the coordinator makes one exec per machine (the
manifest of newly committed chunks), pulls those outputs into a per-machine staging folder, checks sha256 and moves
them into --to if absent (first copy wins). Work starts on the first machine that is ready; later machines take a
share as they arrive; a machine not ready within --place-timeout is given up. Idle machines take the undone work of
lost machines, else the tail half of the busiest machine's list, else copies of the chunks of a machine gone quiet
(tail speculation). Lost machines are replaced; a sim and the stages that read it stay on one machine and resume
elsewhere from its harvested units and checkpoint. Everything is released at the end, on Ctrl-C and on SIGTERM;
re-running the same command resumes. Each machine also releases itself after --idle-s with no job running, so a
killed coordinator leaks nothing for long. Credits: the job's credits_per_gpu_minute, else the 1-GPU offer's price
for the card; at the end, the credits each machine actually spent. Needs gpujob.py and gpujob_core.py beside it.
Standard library only.
"""
from __future__ import annotations

import json, os, shlex, shutil, signal, statistics, subprocess, sys, threading, time, uuid

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import gpujob  # noqa: E402
from gpujob_core import Job, fmt_s, now, out, quiet, read_json, unit_files, write_atomic, write_json  # noqa: E402

RUNNER = [gpujob.ME, os.path.join(os.path.dirname(gpujob.ME), "gpujob_core.py")]  # pushed to every machine


# ---------------------------------------------------------------------------------------------- voyager transport
# Voyager GPU machines through the `voyager machine` CLI: one CLI process per call, answering JSON. Mutations carry a
# stable request id and are retried with the same id, so nothing is leased, run or charged twice.
# GPUJOB_VOYAGER_CLI overrides the CLI command line; GPUJOB_MACHINE_PREFIX names the machines.
TERMINAL_JOB = {"succeeded", "failed", "cancelled", "lost"}
GONE = {"released", "failed", "expired", "stopped"}


class VoyagerError(RuntimeError):
    def __init__(self, code, message, retryable=False, answer=None):
        super().__init__("%s: %s" % (code, message))
        self.code, self.retryable, self.answer = code, retryable, answer or {}


class VoyagerTransport:
    """One machine. `name` must be lowercase [a-z0-9._-]; `gpu` None lets Voyager pick its default card."""

    def __init__(self, name, gpus=1, gpu=None, project=".", cli=None, image=None, idle_s=None, log=None, cpu=None,
                 ram_gib=None):
        self.name, self.gpus, self.gpu, self.image, self.idle_s = name, gpus, gpu, image, idle_s
        self.cpu, self.ram_gib = cpu, ram_gib
        self.project = os.path.abspath(project)
        self.cli = shlex.split(cli or os.environ.get("GPUJOB_VOYAGER_CLI") or "voyager")
        self.run_id = uuid.uuid4().hex[:8]
        self.calls = 0
        self.machine = {}
        self.log = log or (lambda line: None)

    # -- plumbing ---------------------------------------------------------------------------------
    def _call(self, verb, body, mutation=False, request_id=None, attempts=4, timeout=900):
        body = dict(body, directory=self.project)
        if mutation:
            body["requestId"] = request_id or "%s-%s-%s-%d" % (self.name, verb, self.run_id, self.calls)
        self.calls += 1
        delay = 2.0
        for attempt in range(attempts):
            try:
                done = subprocess.run(
                    self.cli + ["machine", verb, "--input", json.dumps(body), "--json"],
                    cwd=self.project, capture_output=True, text=True, timeout=timeout,
                )
                answer = _json(done.stdout)
            except subprocess.TimeoutExpired:
                answer = {"ok": False, "error": {"code": "TIMEOUT", "message": "CLI timed out", "retryable": True}}
            if answer is None:
                answer = {"ok": False, "error": {"code": "UNREADABLE", "retryable": True,
                                                 "message": (done.stderr or done.stdout)[-400:]}}
            if answer.get("ok", True) is not False:
                return answer.get("result", answer)
            error = answer.get("error") or {}
            # Mutations retry with the same request id: the API answers a repeat with the original response.
            retry = error.get("retryable") or error.get("code") in {"SUBMISSION_UNCERTAIN", "TIMEOUT", "UNREADABLE"}
            if not retry or attempt == attempts - 1:
                raise VoyagerError(error.get("code", "ERROR"), error.get("message", "failed"),
                                   bool(error.get("retryable")), answer)
            self.log("voyager %s %s: %s, retrying" % (verb, self.name, error.get("code")))
            time.sleep(delay)
            delay = min(delay * 2, 30)

    # -- the transport interface --------------------------------------------------------------------
    def start_machine(self, wait_s=900):
        """Lease (idempotent for this transport instance) and wait until ready. Returns the machine record."""
        body = {"name": self.name, "gpus": self.gpus}
        body.update({k: v for k, v in (("gpu", self.gpu), ("image", self.image), ("idleS", self.idle_s),
                                       ("cpu", self.cpu), ("ramGib", self.ram_gib)) if v is not None})
        answer = self._call("lease", body, mutation=True, request_id="%s-lease-%s" % (self.name, self.run_id))
        self.machine = answer.get("machine", answer)
        deadline = time.monotonic() + wait_s
        while self.machine.get("state") != "ready":
            if self.machine.get("state") in GONE | {"paused"}:
                raise VoyagerError("NOT_READY", "machine %s is %s" % (self.name, self.machine.get("state")))
            if time.monotonic() > deadline:
                raise VoyagerError("NOT_READY", "machine %s not ready after %d s" % (self.name, wait_s), True)
            left = max(1, min(120, int(deadline - time.monotonic())))
            answer = self._call("wait", {"machine": self.name, "timeout": left}, timeout=left + 120)
            self.machine = answer.get("machine", answer)
            if answer.get("progress"):
                self.log("voyager %s: %s" % (self.name, answer["progress"]))
        return self.machine

    def push(self, paths):
        """Upload project-relative paths (files or folders); unchanged files are skipped by hash."""
        return self._call("sync", {"machine": self.name, "action": "push", "include": list(paths)}, mutation=True)

    def exec(self, argv, detach=False, env=None, cwd="/project", name=None, timeout_s=None):
        """Run argv. detach=True returns at once with job_id; otherwise waits up to ~100 s and returns
        state, exit_code and log (a longer job comes back with background: true and keeps running)."""
        body = {"machine": self.name, "argv": list(argv), "cwd": cwd, "detach": detach}
        body.update({k: v for k, v in (("env", env), ("name", name), ("timeoutS", timeout_s)) if v})
        return self._call("exec", body, mutation=True)

    def job(self, job_id):
        return self._call("job", {"job": job_id, "action": "status"})

    def run(self, argv, cwd="/project"):
        """Foreground exec returning (exit_code, log); for short commands such as `gpujob status --json`."""
        answer = self.exec(argv, cwd=cwd)
        if answer.get("background"):
            raise VoyagerError("SLOW_EXEC", "%s took over 100 s" % " ".join(argv[:3]), True)
        return answer.get("exit_code"), answer.get("log") or ""

    def alive(self):
        """True while the machine is ready; False once it is released, failed, paused or gone."""
        try:
            self.machine = self._call("status", {"machine": self.name}, attempts=2)
            self.machine = self.machine.get("machine", self.machine)
        except VoyagerError as error:
            if error.code == "NOT_FOUND":
                return False
            raise
        return self.machine.get("state") == "ready"

    def release(self):
        """Release and confirm; safe to call twice. Returns the machine's final spend in credits."""
        answer = self._call("release", {"machine": self.name}, mutation=True,
                            request_id="%s-release-%s" % (self.name, self.run_id))
        self.machine = answer.get("machine", answer) or self.machine
        billing = self.machine.get("billing") or {}
        spent = billing.get("spent_credits")
        return float(spent if spent is not None else 100 * float(billing.get("spent_usd") or 0.0))

    def credits_per_gpu_minute(self):
        """The 1-GPU price of this machine's card (the first offer is the card a lease would get)."""
        body = dict({"gpu": self.gpu} if self.gpu else {}, gpus=1)
        offers = (self._call("offers", body, attempts=2) or {}).get("offers") or []
        return float((offers[0] if offers else {}).get("credits_per_minute") or 0.0)


def _json(text):
    """The CLI's JSON answer (tolerates a banner line before it)."""
    text = (text or "").strip()
    return quiet(json.loads, text) if text.startswith("{") else quiet(json.loads, text[text.find("{"):]) \
        if "{" in text else None


class FanoutVoyager:
    """The fan-out transport interface over VoyagerTransport. Each machine syncs through its own mirror folder
    (--to/.gpujob-voyager/<name>/, laid out like /project), so sync never sees another machine's files."""

    BIG = 60000  # foreground output above this comes back through a pulled file (exec output is truncated)

    def __init__(self, a):
        self.gpus = a.gpus_per_machine
        gpu = getattr(a, "gpu_type", None)
        self.gpu = None if gpu in (None, "", "default") else gpu
        self.root = os.path.join(os.path.abspath(a.to), ".gpujob-voyager")
        self.prefix = os.environ.get("GPUJOB_MACHINE_PREFIX", "gpujob")
        self.say = lambda line: out("GPUJOB voyager " + line)
        self.placing = {}  # i -> VoyagerTransport while its lease is being placed (for cancel)
        self.shape = dict(idle_s=a.idle_s, cpu=a.cpu, ram_gib=a.ram_gib)
        self.spent = 0.0  # credits the released machines reported

    def start_machine(self, i):
        name = "%s-m%d-%s" % (self.prefix, i, uuid.uuid4().hex[:6])
        mirror = os.path.join(self.root, name)
        os.makedirs(mirror, exist_ok=True)
        t = VoyagerTransport(name, gpus=self.gpus, gpu=self.gpu, project=mirror, log=self.say, **self.shape)
        m = {"t": t, "mirror": mirror, "ref": name, "job": None, "pulled": {}, "work": "/project"}
        self.placing[i] = t
        try:
            t.start_machine()
        except Exception:
            self._release(t)
            raise
        finally:
            self.placing.pop(i, None)
        return m

    def cancel(self, i):
        """Give up on machine i while it is still being placed (--place-timeout, or the job finished)."""
        if i in self.placing:
            self._release(self.placing[i])

    def push(self, m, local, remote_rel):
        target = os.path.join(m["mirror"], remote_rel)
        os.makedirs(os.path.dirname(target), exist_ok=True)
        if os.path.abspath(local) != os.path.abspath(target):
            shutil.copyfile(local, target)
        m["t"].push([remote_rel])  # sha256-checked by sync; unchanged files are skipped

    def exec(self, m, argv, log_rel=None):
        t = m["t"]
        if log_rel:  # detached: tee into log_rel and keep the job's own log for Voyager's tray
            script = 'set -o pipefail; "$@" 2>&1 | tee -a "$GPUJOB_LOG"'
            j = t.exec(["bash", "-c", script, "gpujob"] + list(argv), detach=True, env={"GPUJOB_LOG": log_rel},
                       name="gpujob-run")
            m["job"] = j["job_id"]
            m["pulled"].clear()
            return None
        out = ".gpujob-voyager-out-%s.txt" % uuid.uuid4().hex[:8]
        script = ('o=$("$@"); rc=$?; if [ ${#o} -lt %d ]; then printf %%s "$o"; else printf %%s "$o" > %s; '
                  'printf "@@GPUJOB_FILE %s"; fi; exit $rc' % (self.BIG, out, out))
        rc, text = t.run(["bash", "-c", script, "gpujob"] + list(argv))
        if text.startswith("@@GPUJOB_FILE "):
            t._call("sync", {"machine": t.name, "action": "pull", "include": [out], "to": "."}, mutation=True)
            path = os.path.join(m["mirror"], out)
            with open(path) as handle:
                text = handle.read()
            os.remove(path)
            t.run(["rm", "-f", out])
        return rc, text

    def poll(self, m):
        if not m["job"]:
            return -1
        j = m["t"].job(m["job"])
        state = j.get("state")
        if state not in TERMINAL_JOB:
            return None
        if state == "succeeded":
            return 0
        code = j.get("exit_code")
        return code if isinstance(code, int) and code not in (0, -1) else 1

    def fetch(self, m, rel, local):
        """One pull per output folder per poll (hash-verified, unchanged files skipped), then copy from the mirror.
        A second fetch of the same file (gpujob's hash check failed) pulls that one file again."""
        folder = os.path.dirname(rel)
        mine = os.path.join(m["mirror"], rel)
        again = m["pulled"].get(rel, 0) > 0
        if again:
            m["t"]._call("sync", {"machine": m["t"].name, "action": "pull", "include": [rel], "to": "."},
                         mutation=True)
        elif not os.path.isfile(mine) or folder not in m["pulled"]:
            m["t"]._call("sync", {"machine": m["t"].name, "action": "pull", "include": [folder or "."], "to": ".",
                                  "exclude": [".tmp", "**/.tmp/**", ".*"]}, mutation=True)
            m["pulled"][folder] = time.time()
        m["pulled"][rel] = m["pulled"].get(rel, 0) + 1
        shutil.copyfile(mine, local)

    def alive(self, m):
        try:
            return m["t"].alive()
        except VoyagerError:
            return True  # an unreadable status is not a lost machine; the next poll decides

    def release(self, m):
        self._release(m["t"])

    def release_ref(self, ref):
        self._release(VoyagerTransport(ref, project=self.root))

    def rate(self):
        """Credits per GPU-second when the job sets no price."""
        os.makedirs(self.root, exist_ok=True)
        return VoyagerTransport("offers", gpu=self.gpu, project=self.root).credits_per_gpu_minute() / 60

    def _release(self, t):
        try:
            spent = t.release()
            self.spent += spent
            self.say("released %s %.1f credits" % (t.name, spent))
        except VoyagerError as error:
            if error.code != "NOT_FOUND":
                self.say("release %s failed: %s (check machine list)" % (t.name, error))


TRANSPORTS = {"voyager": FanoutVoyager}


# ---------------------------------------------------------------------------------------------- fanout
def cmd_fanout(a):
    """The coordinator (see the module docstring). Returns 0 once every wanted chunk is harvested."""
    job = Job.load(a.job)
    dest = os.path.abspath(a.to or os.path.join(job.workdir, f"{job.name}-out"))
    os.makedirs(dest, exist_ok=True)
    a.to = dest
    fpath = os.path.join(dest, ".gpujob-fanout.json")
    if a.transport not in TRANSPORTS:  # a plug-in: gpujob_<name>.py next to this file, class Transport
        TRANSPORTS[a.transport] = __import__(f"gpujob_{a.transport}").Transport
    T = TRANSPORTS[a.transport](a)
    for ref in (read_json(fpath, {}) or {}).get("live_refs", []):  # a killed coordinator must not leak machines
        T.release_ref(ref)
    if not job.rate and hasattr(T, "rate"):  # price from current offers; each machine's gpujob reports it too
        job.rate = quiet(T.rate) or 0.0
        job.spec["credits_per_gpu_minute"] = round(job.rate * 60, 4)
    pushes = [p for p in (a.push or "").split(",") if p]
    # sequential stages and their consumers share one machine (machines have no shared disk)
    pinned = job.dependents({s.name for s in job.stages if s.kind == "sequential"})
    is_pin = lambda x: x.split(":")[0] in pinned
    items = [f"{s.name}:{c}" for s in job.stages for c in s.chunks]
    wanted = [x for x in items if job.by[x.split(":")[0]].harvest]
    jpath = os.path.join(dest, ".gpujob-remote-job.json")
    write_json(jpath, dict(job.spec, workdir="."))
    lock = threading.RLock()
    machines, tries, secs, slices, spec, placing, mlog = [], {}, {}, [], set(), {}, {}
    st = dict(starts=0, billed=0.0, rc=1, timeouts=0)
    t0 = last = now()

    def interrupt(*_):
        raise KeyboardInterrupt
    signal.signal(signal.SIGTERM, interrupt)

    def harvested():
        return {f"{s}:{c}" for s, cs in read_json(os.path.join(dest, ".gpujob-harvest.json"), {}).items() for c in cs}

    def pending():
        return sum(1 for p in placing.values() if not p["abandoned"])

    def save():
        write_json(fpath, dict(live_refs=[m["ref"] for m in machines] + [p["m"]["ref"] for p in placing.values()
                                                                          if p.get("m")], t=now()))

    def drop(m, state):
        T.release(m)
        st["billed"] += (now() - m["t_start"]) * a.gpus_per_machine
        mlog[m["i"]].update(state=state, released_s=round(now() - t0, 1),
                            billed_gpu_seconds=round((now() - m["t_start"]) * a.gpus_per_machine, 1))
        if m in machines:
            machines.remove(m)
        save()

    def work_for(m, hv):
        """A newly ready machine: its share of the work nobody runs yet. Then: undone chunks nobody runs (the pinned
        group moves whole), else the tail half of the busiest machine's list, else speculative copies of the chunks
        of a machine that has committed nothing for 1.5x the median chunk time."""
        busy = [o for o in machines if not o["idle"] and o is not m]
        owned = {x for o in busy for x in o["assign"] if x not in hv}
        while slices:
            sl = [x for x in slices.pop(0) if x not in hv and x not in owned]
            if sl:
                return sl
        free = [x for x in items if x not in hv and x not in owned and tries.get(x, 0) <= 3
                and (x in wanted or is_pin(x))]
        if not any(is_pin(x) and x in wanted for x in free):
            free = [x for x in free if not is_pin(x)]
        if free:
            return free
        left_of = lambda o: [x for x in o["assign"] if x not in hv and x not in o["done"] and not is_pin(x)]
        victim = max(busy, key=lambda o: len(left_of(o)), default=None)
        if victim and len(left_of(victim)) > 1:  # both may finish the middle; first harvested wins
            return left_of(victim)[len(left_of(victim)) // 2:]
        med = statistics.median(secs.values()) if secs else None
        quiet_ = [o for o in busy if med and now() - o["progress_t"] > 1.5 * med + a.poll
                  and [x for x in left_of(o) if x not in spec]]
        if not quiet_:
            return []
        o = min(quiet_, key=lambda o: o["progress_t"])
        dup = [x for x in left_of(o) if x not in spec]
        spec.update(dup)
        out(f"GPUJOB event speculate m{m['i']} copies {len(dup)} chunk(s) of m{o['i']} (quiet {fmt_s(now() - o['progress_t'])})")
        return dup

    def launch(m, assign):
        if any(is_pin(x) for x in assign) and not m.get("has_pin"):
            # the sim group moves here: push back its harvested units and newest checkpoint so --resume continues
            m["has_pin"] = True
            for s_ in job.stages:
                if s_.kind == "sequential":
                    files = unit_files(os.path.join(dest, s_.out_rel), s_.unit_glob)
                    ck = unit_files(dest, s_.checkpoint) if s_.checkpoint else []
                    for f in files + sorted(ck, key=os.path.getmtime)[-1:]:
                        T.push(m, f, os.path.relpath(f, dest))
                    if files or ck:
                        out(f"GPUJOB event restore m{m['i']} {s_.name} units={len(files)} checkpoint={len(ck) > 0}")
        m.update(assign=list(assign), idle=False, progress_t=now())
        for x in assign:
            tries[x] = tries.get(x, 0) + 1
        ids = os.path.join(dest, f".gpujob-only-m{m['i']}.txt")
        write_atomic(ids, "\n".join(assign))
        T.push(m, ids, "only.txt")
        T.exec(m, ["python3", "gpujob.py", "run", "job.json", "--state", ".gpujob/" + job.name, "--only", "@only.txt"],
               log_rel="gpujob.log")

    def boot():
        with lock:
            i = st["starts"]
            st["starts"] += 1
            pl = placing[i] = dict(t_req=now(), m=None, abandoned=False)
            mlog[i] = dict(m=i, requested_s=round(now() - t0, 1), state="placing")
        m = None
        try:
            m = T.start_machine(i)
            m.update(i=i, t_start=now(), done=set(), cursor=0.0, idle=True, assign=[], ready=False, progress_t=now(),
                     staging=os.path.join(dest, ".gpujob-staging", f"m{i}"))
            with lock:
                pl["m"] = m
                save()
            if pl["abandoned"]:
                raise RuntimeError("placed after --place-timeout")
            for f in RUNNER + [jpath]:
                T.push(m, f, "job.json" if f == jpath else os.path.basename(f))
            for p in pushes:
                src = os.path.join(job.workdir, p)
                for f in ([os.path.join(dp, x) for dp, _, fs in os.walk(src) for x in fs] if os.path.isdir(src)
                          else [src]):
                    T.push(m, f, os.path.relpath(f, job.workdir))
            with lock:  # work is chosen when the machine is ready, not when it was requested
                if pl["abandoned"]:
                    raise RuntimeError("placed after --place-timeout")
                machines.append(m)
                assign = work_for(m, harvested())
                if assign:
                    launch(m, assign)
                m["ready"] = True
                mlog[i].update(state="running", ready_s=round(now() - t0, 1))
                del placing[i]
                save()
            out(f"GPUJOB event machine_up m{i} after {fmt_s(now() - pl['t_req'])} chunks={len(assign)}")
        except Exception as ex:
            with lock:
                placing.pop(i, None)
                if mlog[i]["state"] == "placing":
                    mlog[i]["state"] = "place_timeout" if pl["abandoned"] else "start_failed"
                if not pl["abandoned"]:
                    out(f"GPUJOB event machine_start_failed m{i} {str(ex)[:200]}")
                if m and "t_start" in m:
                    drop(m, mlog[i]["state"])

    def split_first(todo, n):
        free = [x for x in todo if not is_pin(x)]
        parts = [free[k * len(free) // n:(k + 1) * len(free) // n] for k in range(n)]
        parts[0] = [x for x in todo if is_pin(x)] + parts[0]
        return parts

    try:
        hv = harvested()
        todo = [x for x in items if x not in hv]
        out(f"GPUJOB fanout start job={job.name} machines={a.machines}x{a.gpus_per_machine} chunks={len(todo)} "
            f"to={dest}")
        if [x for x in wanted if x not in hv]:
            slices.extend(split_first(todo, a.machines))
            for _ in range(a.machines):
                threading.Thread(target=boot, daemon=True).start()
        while True:
            hv = harvested()
            left = [x for x in wanted if x not in hv]
            if not left:
                st["rc"] = 0
                break
            time.sleep(max(0.0, a.poll - (now() - last)))
            last = now()
            with lock:
                for i, pl in list(placing.items()):  # give up on machines that don't place in time
                    if not pl["abandoned"] and now() - pl["t_req"] > a.place_timeout:
                        pl["abandoned"] = True
                        st["timeouts"] += 1
                        out(f"GPUJOB event machine_place_timeout m{i} after {fmt_s(now() - pl['t_req'])}; "
                            f"carrying on with {len(machines)} machine(s)")
                        quiet(getattr(T, "cancel", lambda i: None), i)
                        if pl.get("m"):
                            quiet(T.release, pl["m"])
            for m in list(machines):
                with lock:  # boot() threads launch under the same lock
                    if not m["ready"]:
                        continue
                    # before the manifest, so it sees the run's last commits; an unreachable machine reads as running
                    # and the alive() check below decides whether it is lost
                    code = quiet(T.poll, m) if m["assign"] else 0
                    try:
                        r = T.exec(m, ["python3", "gpujob.py", "manifest", ".gpujob/" + job.name,
                                       "--after", repr(m["cursor"])])
                        res = json.loads(r[1]) if r[0] == 0 else None
                    except Exception:
                        res = None
                    if res is not None:
                        try:
                            new, bad = gpujob.harvest_into(res["manifest"], lambda o, rel, tmp, m=m: T.fetch(
                                m, os.path.join(o, rel), tmp), dest, m["staging"], log=out)
                            if not bad:
                                m["cursor"] = res["cursor"]
                            if new:
                                m["progress_t"] = now()
                            m["done"] = {f"{s}:{c}" for s, ids in res["done"].items() for c in ids}
                            secs.update((k, r["seconds"]) for info in res["manifest"].values()
                                        for k, r in info["chunks"].items() if r["seconds"] is not None)
                        except Exception as ex:
                            out(f"GPUJOB event harvest_error m{m['i']} {str(ex)[:200]}")
                    if quiet(T.alive, m) is False:  # an error reading status is not a lost machine
                        out(f"GPUJOB event machine_lost m{m['i']} (its unharvested chunks go back to the pool)")
                        drop(m, "lost")
                        continue
                    if code is not None and not m["idle"]:
                        if code not in (0, -1):
                            out(f"GPUJOB event machine_run_exit m{m['i']} code={code}")
                        m["idle"] = True
            hv = harvested()
            left = [x for x in wanted if x not in hv]
            if not left:
                continue
            with lock:
                for m in [m for m in machines if m["idle"] and m["ready"]]:
                    give = work_for(m, hv)
                    if give:
                        out(f"GPUJOB event assign m{m['i']} chunks={len(give)}")
                        launch(m, give)
                owned = {x for o in machines if not o["idle"] for x in o["assign"]}
                orphans = [x for x in left if x not in owned and tries.get(x, 0) <= 3]
                if orphans and len(machines) + pending() + st["timeouts"] < a.machines and st["starts"] < 3 * a.machines:
                    out(f"GPUJOB event machine_replacing for {len(orphans)} chunks")
                    threading.Thread(target=boot, daemon=True).start()
                if not machines and not pending():
                    out(f"GPUJOB error no machines left; {len(left)} chunks not harvested")
                    break
                if not owned and not pending() and not orphans:
                    out(f"GPUJOB error chunks failed on every try: {' '.join(left[:10])}")
                    break
            billed = st["billed"] + sum((now() - m["t_start"]) * a.gpus_per_machine for m in machines)
            n, live = len(wanted), max(1, len(machines)) * a.gpus_per_machine
            eta = statistics.median(secs.values()) * -(-len(left) // live) if secs else None
            out(f"GPUJOB progress {int(100 * (n - len(left)) / n)}% {n - len(left)}/{n} chunks harvested "
                f"eta {'?' if eta is None else str(int(eta)) + 's'} {billed * job.rate:.0f} credits | machines "
                f"{len(machines)} live {pending()} placing")
    finally:
        with lock:  # machines still being placed are given up too; their threads release them when they return
            for i, pl in placing.items():
                pl["abandoned"] = True
                quiet(getattr(T, "cancel", lambda i: None), i)
                if pl.get("m"):
                    quiet(T.release, pl["m"])
            for m in list(machines):
                drop(m, mlog[m["i"]]["state"] if mlog[m["i"]]["state"] != "running" else "released")
        deadline = now() + 60
        while placing and now() < deadline:
            time.sleep(0.2)
        if placing:
            out(f"GPUJOB warning machine request(s) {sorted(placing)} still placing; the transport releases them "
                "when they return")
        save()
        credits = getattr(T, "spent", 0.0) or st["billed"] * job.rate  # what the machines reported, else estimated
        write_json(os.path.join(dest, ".gpujob-fanout-report.json"), dict(
            rc=st["rc"], wall_s=round(now() - t0, 1), billed_gpu_seconds=round(st["billed"], 1), credits=round(credits, 1),
            machine_starts=st["starts"], speculative=len(spec), machines=[mlog[i] for i in sorted(mlog)]))
    ready = " ".join(f"m{i}:{mlog[i].get('ready_s', mlog[i]['state'])}" for i in sorted(mlog))
    out(f"GPUJOB fanout end {'done' if st['rc'] == 0 else 'incomplete'} wall {fmt_s(now() - t0)} machines started "
        f"{st['starts']} (ready at s: {ready}) billed {fmt_s(st['billed'])} GPU {credits:.0f} credits speculative {len(spec)} "
        f"exit={st['rc']}")
    return st["rc"]


# ---------------------------------------------------------------------------------------------- cli
F = float
CLI = {"fanout": ("run one job over several machines", [
    ("job",), ("--machines", int, "how many machines", 1), ("--gpus-per-machine", int, "GPUs on each", 1),
    ("--transport", str, "voyager, or <name> for a plug-in gpujob_<name>.py beside this file", "voyager"),
    ("--to", str, "durable output folder (default <workdir>/<name>-out)"),
    ("--push", str, "comma list of paths (relative to workdir) to copy onto each machine"),
    ("--poll", F, "seconds between machine polls (>= 30 for real machines)", 30.0),
    ("--place-timeout", F, "give up on a machine not ready after this many seconds", 600.0),
    ("--gpu-type", str, "GPU type (default: the transport's own)"),
    ("--cpu", int, "CPU cores per machine (default: the machine's own)"),
    ("--ram-gib", int, "RAM per machine in GiB (default: the machine's own)"),
    ("--idle-s", int, "a machine releases itself after this many seconds with no job running", 900)])}


def main(argv=None, cli=None, transports=None):
    TRANSPORTS.update(transports or {})
    return gpujob.main(argv, dict(CLI, **(cli or {})), {"fanout": cmd_fanout})


if __name__ == "__main__":
    sys.exit(main())

"""Save a copy of a Blender scene that carries its own files, ready to send to a GPU machine.

    blender -b --factory-startup scene.blend --python pack_scene.py -- \\
        --out render/scene.blend [--make-local]

Packs every packable file (images, fonts, sounds, volumes) into the copy, keeps the paths of what
cannot be packed relative to the copy, and leaves the original .blend untouched. --make-local
copies linked library data into the copy, so no library files are needed.

Prints ``PACK_SCENE_JSON {...}`` and writes the same beside the copy (<out>.pack.json):
``external``: files the render still reads from disk, each with its path relative to the copy's
folder (sync these with the same relative layout) or ``outside`` when it is not under that folder;
``missing``: referenced files that do not exist (the render draws without them);
``unbaked``: simulations that would be computed during the render (bake them before splitting
frames across processes); ``scripted_drivers``: Python drivers, which only run with -y
(--enable-autoexec). Every failure prints ``pack_scene: error: ...`` and exits non-zero.
"""

import argparse
import json
import os
import re
import sys

import bpy

ID_COLLECTIONS = (
    "objects", "meshes", "materials", "node_groups", "collections", "images", "textures", "worlds",
    "lights", "cameras", "curves", "armatures", "actions", "fonts", "volumes", "particles",
    "grease_pencils", "lattices", "metaballs", "scenes", "sounds", "movieclips", "cache_files",
)


class Failure(Exception):
    pass


def arguments():
    argv = sys.argv[sys.argv.index("--") + 1 :] if "--" in sys.argv else []
    parser = argparse.ArgumentParser(prog="pack_scene.py")
    parser.add_argument("--out", required=True, help="Path of the packed copy (.blend)")
    parser.add_argument("--make-local", action="store_true", help="Copy linked library data into the copy")
    return parser.parse_args(argv)


def make_local():
    """Linked data becomes local data; repeat until nothing links (data can link other data)."""
    for _ in range(8):
        linked = [
            datablock
            for name in ID_COLLECTIONS
            for datablock in getattr(bpy.data, name, [])
            if datablock.library is not None
        ]
        if not linked:
            for library in list(bpy.data.libraries):
                bpy.data.libraries.remove(library)
            return
        for datablock in linked:
            datablock.make_local()
    remaining = sum(1 for name in ID_COLLECTIONS for d in getattr(bpy.data, name, []) if d.library is not None)
    if remaining:
        raise Failure("%d linked datablocks could not be made local" % remaining)


def sequence(path):
    """The files that number the same image sequence (prefix, digit run, suffix)."""
    folder, name = os.path.split(path)
    match = re.search(r"(\d+)(?!.*\d)", name)
    if not match or not os.path.isdir(folder):
        return [path]
    prefix, suffix = name[: match.start()], name[match.end() :]
    pattern = re.compile(re.escape(prefix) + r"\d+" + re.escape(suffix) + r"$")
    return sorted(os.path.join(folder, entry) for entry in os.listdir(folder) if pattern.match(entry)) or [path]


def external_files():
    """Files the scene still reads from disk after packing: (kind, name, paths)."""
    found = []
    for collection, kind in (
        (bpy.data.libraries, "library"),
        (bpy.data.images, "image"),
        (bpy.data.fonts, "font"),
        (bpy.data.volumes, "volume"),
        (bpy.data.cache_files, "cache"),
        (bpy.data.sounds, "sound"),
        (bpy.data.movieclips, "movieclip"),
    ):
        for datablock in collection:
            if getattr(datablock, "packed_file", None) is not None:
                continue
            raw = getattr(datablock, "filepath", "")
            if not raw or raw == "<builtin>":
                continue
            if kind == "image" and datablock.source not in {"FILE", "SEQUENCE", "TILED", "MOVIE"}:
                continue
            resolved = os.path.normpath(bpy.path.abspath(raw, library=getattr(datablock, "library", None)))
            if kind == "image" and datablock.source == "TILED":
                paths = [resolved.replace("<UDIM>", str(tile.number)) for tile in datablock.tiles]
            elif (kind == "image" and datablock.source == "SEQUENCE") or getattr(datablock, "is_sequence", False):
                paths = sequence(resolved)
            else:
                paths = [resolved]
            found.append((kind, datablock.name, paths))
    blend = bpy.data.filepath
    stem = os.path.splitext(os.path.basename(blend))[0]
    for obj in bpy.data.objects:
        for modifier in obj.modifiers:
            cache = getattr(modifier, "point_cache", None)
            if cache is not None and cache.is_baked and cache.use_disk_cache:
                folder = (
                    bpy.path.abspath(cache.filepath)
                    if cache.use_external and cache.filepath
                    else os.path.join(os.path.dirname(blend), "blendcache_" + stem)
                )
                found.append(("cache", "%s:%s" % (obj.name, modifier.name), walk(folder)))
            directory = getattr(modifier, "bake_directory", "")
            if modifier.type == "NODES" and directory and os.path.isdir(bpy.path.abspath(directory)):
                found.append(("cache", "%s:%s" % (obj.name, modifier.name), walk(bpy.path.abspath(directory))))
    return found


def walk(folder):
    files = []
    for root, _dirs, names in os.walk(folder):
        files += [os.path.join(root, name) for name in sorted(names)]
    return files or [folder]


def unbaked():
    found = []
    for scene in bpy.data.scenes:
        if scene.rigidbody_world is not None and not scene.rigidbody_world.point_cache.is_baked:
            found.append("%s: rigid body world" % scene.name)
    for obj in bpy.data.objects:
        for modifier in obj.modifiers:
            cache = getattr(modifier, "point_cache", None)
            if cache is not None and not cache.is_baked:
                found.append("%s: %s" % (obj.name, modifier.name))
    return found


def scripted_drivers():
    found = []
    for name in ("objects", "materials", "scenes", "meshes", "node_groups", "shape_keys", "armatures"):
        for datablock in getattr(bpy.data, name, []):
            animation = getattr(datablock, "animation_data", None)
            for fcurve in getattr(animation, "drivers", None) or []:
                driver = fcurve.driver
                if driver.type == "SCRIPTED" and not driver.is_simple_expression:
                    found.append("%s: %s" % (datablock.name, fcurve.data_path))
    return found


def main():
    options = arguments()
    source = bpy.data.filepath
    if not source:
        raise Failure("open a saved .blend: blender -b --factory-startup scene.blend --python pack_scene.py -- ...")
    out = os.path.abspath(options.out)
    if not out.endswith(".blend"):
        raise Failure("--out must name a .blend file")
    if out == os.path.abspath(source):
        raise Failure("--out is the open scene; pick a new path so the original stays untouched")
    os.makedirs(os.path.dirname(out), exist_ok=True)
    if options.make_local:
        make_local()
    bpy.ops.file.pack_all()
    bpy.ops.file.make_paths_relative()
    bpy.context.preferences.filepaths.save_version = 0  # no .blend1 beside the copy
    # relative_remap rewrites the remaining // paths for the copy's folder.
    bpy.ops.wm.save_as_mainfile(filepath=out, relative_remap=True, compress=True)
    folder = os.path.dirname(out)
    external, missing = [], []
    for kind, name, paths in external_files():
        present = [path for path in paths if os.path.exists(path)]
        if not present:
            missing.append({"kind": kind, "name": name, "paths": paths[:5]})
            continue
        relative = [os.path.relpath(path, folder) for path in present]
        outside = any(path.startswith("..") or os.path.isabs(path) for path in relative)
        external.append({"kind": kind, "name": name, "files": len(present), "paths": relative[:20], "outside": outside})
    report = {
        "source": source,
        "packed": out,
        "bytes": os.path.getsize(out),
        "packed_files": sum(1 for name in ("images", "fonts", "sounds", "volumes")
                            for d in getattr(bpy.data, name) if getattr(d, "packed_file", None) is not None),
        "external": external,
        "missing": missing,
        "unbaked": unbaked(),
        "scripted_drivers": scripted_drivers(),
    }
    with open(out + ".pack.json", "w", encoding="utf-8") as handle:
        json.dump(report, handle, indent=2)
    print("PACK_SCENE_JSON %s" % json.dumps(report), flush=True)


if __name__ == "__main__":
    try:
        main()
    except Failure as error:
        print("pack_scene: error: %s" % error, file=sys.stderr, flush=True)
        sys.exit(2)
    except Exception as error:
        print("pack_scene: error: %s: %s" % (type(error).__name__, error), file=sys.stderr, flush=True)
        sys.exit(1)
